<?php
namespace App\Http\Controllers\Tenant;
use App\Http\Controllers\Controller; use App\Models\{Account,Expense,JournalLine,Payment}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AccountingController extends Controller { public function index(Request $r){$balances=JournalLine::select('account_id',DB::raw('SUM(debit) debit'),DB::raw('SUM(credit) credit'))->with('account')->groupBy('account_id')->get();$income=$balances->filter(fn($x)=>$x->account?->type==='income')->sum(fn($x)=>$x->credit-$x->debit);$expense=$balances->filter(fn($x)=>$x->account?->type==='expense')->sum(fn($x)=>$x->debit-$x->credit);return view('tenant.accounting',['balances'=>$balances,'income'=>$income,'expense'=>$expense,'payments'=>Payment::latest()->limit(10)->get(),'expenses'=>Expense::latest()->limit(10)->get()]);} public function ledger(Request $r){$q=JournalLine::with(['account','journalEntry'])->latest('id');if($r->filled('account_id'))$q->where('account_id',$r->account_id);return view('tenant.ledger',['lines'=>$q->paginate(50)->withQueryString(),'accounts'=>Account::orderBy('code')->get()]);} }
